local Kr=pb._model[Jr]
if Kr~=nil then
return Kr or nil
end
local Lr,Mr={},false
local Nr=math.max(0.3,tonumber(Ir and Ir.cd)or 2)
local Or=math.min(1,(tonumber(Hr and Hr.n)or 1)/4)
