end
end
if type(Xr.ampFrom)==Gje[2012]and tostring(Xr.ampFrom.kind)==Gje[1856]and(tonumber(Xr.ampFrom.amp)or 0)>0 then
local ts=(type(Xr.secsBy)==Gje[2012]and#Xr.secsBy>0)and Xr.secsBy or{tonumber(Xr.secsSeen)or tonumber(Xr.secs)or 5}
Lr.flames,Mr={amp=tonumber(Xr.ampFrom.amp),secs=ts},true
end
elseif Wr.family==Gje[2250]then
Lr.exec,Mr=tonumber(Xr.below)or 0.25,true
end
end
end
pb._model[Jr]=Mr and Lr or false
return Mr and Lr or nil
end
