if not(FA and FA.n>0)then
return
end
local GA=math.max(1,bb.wave())
local HA=FA.n/GA
local IA
if#FA.hpK>0 then
local JA=table.clone(FA.hpK)
table.sort(JA)
IA=JA[math.floor(#JA/2)+1]
end
local KA=type(P.hunt.starfall)==Gje[2012]and P.hunt.starfall or{}
local LA=(tonumber(KA.runs)or 0)+1
local MA=1/math.min(LA,5)
P.hunt.starfall={runs=LA,perWave=KA.perWave and(KA.perWave+(HA-KA.perWave)*MA)or HA,hpK=IA and(KA.hpK and(KA.hpK+(IA-KA.hpK)*MA)or IA)or KA.hpK,at=os.time()}
local NA,OA
for PA in pairs(FA.waves)do
NA=math.min(NA or PA,PA)
OA=math.max(OA or PA,PA)
end
F.log(1,Gje[2499],string.format(Gje[2500],FA.n,GA,HA,tostring(NA),tostring(OA),IA or 0))
return{n=FA.n,waves=GA,hpK=IA and math.floor(IA*100+0.5)/100 or nil}
end
