function mb.charmSellPlan(_C)
_C=_C or mb.charms()
local aD=mb.charmSlots()
local bD=math.max(1,math.min(aD-2,math.floor(tonumber(O.charmFree)or 2)))
local cD= #_C-(aD-bD)
if cD<=0 then
return{},#_C,aD,bD
end
local dD=mb.charmOn()
local eD={}
for fD,gD in ipairs(_C)do
gD.total=0
for hD,iD in pairs(gD.rolls)do
gD.total=gD.total+iD
if not eD[hD]or iD>(eD[hD].rolls[hD]or 0)then
eD[hD]=gD
end
end
end
local jD={}
for kD,lD in pairs(eD)do
jD[lD]=true
end
local mD={}
for nD,oD in ipairs(_C)do
if not jD[oD]and not oD.worn and oD.uuid~=dD and oD.tier<4 then
table.insert(mD,oD)
end
end
table.sort(mD,function(pD,qD)
if math.abs(pD.total-qD.total)>1e-9 then
return pD.total<qD.total
end
return pD.tier<qD.tier
end)
local rD={}
for sD=1,math.min(cD,#mD)do
table.insert(rD,mD[sD])
end
return rD,#_C,aD,bD
end
