end
local DD= #mb.charms()
if DD>uD- #wD then
local ED=F.gameSaid(AD)
F.log(1,Gje[2540],string.format(Gje[2545],#wD,tostring(ED or CD or Gje[2546])))
F.backoff(Gje[2543],1800)
return
end
cb.add(string.format(Gje[2547],#wD),#wD,Gje[2548],string.format(Gje[2549],vD-DD,vD,table.concat(xD,Gje[2550])))
end
function mb.weatherStrength(FD)
local GD=mb.fx(FD)
local HD=GD.dmg/GD.cd/GD.hp/GD.speed*(1+(GD.range-1)/2)
for JD,KD in pairs(GD.kinds)do
HD=HD*(1+bb.rogueShare(JD)*KD)
end
if GD.ice>0 then
local LD=bb.rogueShare(Gje[2145])
HD=HD*(LD+(1-LD)/(1-GD.ice+GD.ice/gb.modFactor(Gje[2551])))
end
if GD.fly>0 then
HD=HD*(1-GD.fly*0.5)
end
if GD.noCC then
HD=HD*0.95
end
if GD.shroud then
HD=HD*0.9
end
if GD.zap then
HD=HD*0.85
end
return HD/mb.weatherK(FD)
end
mb.WEATHER_K_MIN,mb.WEATHER_K_MAX,mb.WEATHER_K_RUNS=0.5,4,10
function mb.weatherK(MD)
