function mb.weatherLearn()
if bb.withOthers or#game:GetService(Gje[912]):GetPlayers()>1 then
return
end
local OD=bb.huntWeather or mb.weatherNow()
local PD,QD=bb.pred,bb.calRun
if not OD or type(PD)~=Gje[2012]or type(QD)~=Gje[2012]then
return
end
local function RD(SD,TD)
return type(SD)==Gje[2012]and tonumber(SD[TD]or SD[tostring(TD)])or nil
end
local UD={}
for VD=2,bb.wave()do
local WD,XD=RD(QD.alive,VD),RD(PD.aliveAt,VD)
if WD and XD and WD>0 and XD>0 then
table.insert(UD,WD/XD)
end
end
if#UD<3 then
return
end
table.sort(UD)
local YD=UD[math.ceil(#UD/2)]
P.hunt.wk=type(P.hunt.wk)==Gje[2012]and P.hunt.wk or{}
local ZD=P.hunt.wk[tostring(OD)]
local _D=math.min(mb.WEATHER_K_RUNS-1,type(ZD)==Gje[2012]and tonumber(ZD.n)or 0)
local aE=mb.weatherK(OD)
local bE=math.max(1,_D)
local cE=math.exp((bE*math.log(aE)+math.log(aE*YD))/(bE+1))
cE=U.clamp(cE,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(OD),old=ZD}
P.hunt.wk[tostring(OD)]={k=cE,n=(type(ZD)==Gje[2012]and tonumber(ZD.n)or 0)+1,at=os.time()}
F.log(1,Gje[2552],string.format(Gje[2553],tostring(OD),YD,tostring(OD),cE,aE,P.hunt.wk[tostring(OD)].n))
end
