ab.FUSE_RANK={Rare=1,Epic=2,Legendary=3}
function ab.xpFodder(afb)
local bfb=N.session()
local cfb=ab.FUSE_RANK[O.fuseXpRarity]or 2
local dfb={[afb.uuid]=true,[O.evolveUnit]=true}
for efb,ffb in ipairs(V.equipped())do
dfb[ffb.uuid]=true
end
for gfb,hfb in ipairs(P.savedTeam or{})do
dfb[hfb]=true
end
for ifb,jfb in ipairs(P.train and P.train.on and P.train.on.base or{})do
dfb[jfb]=true
end
local kfb,lfb={},0
for mfb,nfb in pairs(bfb.profile_data.collection.owned_units)do
local ofb=N.Units[nfb.unit_id]
local pfb=ofb and ab.FUSE_RANK[ofb.rarity]
if pfb and pfb<=cfb and not dfb[mfb]then
local qfb=bfb.collection:get_unit_by_uuid(mfb)or nfb
if not(nfb._locked or qfb._locked)and not(nfb._equipped_relic or qfb._equipped_relic)then
local rfb,sfb=pcall(N.USC.calculate_xp_gain_from_fuse,afb,{qfb},bfb)
sfb=rfb and tonumber(sfb)or 0
if sfb>0 then
table.insert(kfb,{uuid=mfb,id=nfb.unit_id,xp=sfb,rarity=ofb.rarity})
lfb=lfb+sfb
end
end
end
end
table.sort(kfb,function(tfb,ufb)
if tfb.xp~=ufb.xp then
return tfb.xp<ufb.xp
end
return tfb.uuid<ufb.uuid
end)
local vfb=math.max(0,kb.xpFor(afb.unit_id,kb.cap(afb))-(tonumber(afb.xp)or 0))
local wfb,xfb={},0
for yfb,zfb in ipairs(kfb)do
if xfb>=vfb then
break
end
table.insert(wfb,zfb)
xfb=xfb+zfb.xp
end
return wfb,xfb,vfb,lfb
end
