function ab.autoFuseXp()
if not O.autoFuseXp or O.fuseXpUnit==Gje[933]then
return
end
local Wfb=N.session()
local Xfb=ab.fuseXpTarget(Wfb)
if not Xfb then
return
end
local Yfb=V.name(Xfb.unit_id)
local Zfb,_fb,agb=ab.xpFodder(Xfb)
if agb<=0 then
ab.pickNote.autoFuseXp=nil
return
end
if#Zfb==0 then
ab.pickNote.autoFuseXp=Gje[3145]
return
end
if os.time()-(tonumber(O.fuseXpOnAt)or 0)<30 then
ab.pickNote.autoFuseXp=Gje[3146]
return
end
ab.pickNote.autoFuseXp=nil
if F.req.back.fuseXp and U.now()<F.req.back.fuseXp then
return
end
ab.fuseBatch=ab.fuseBatch or 50
local bgb,cgb,dgb=0,0,{}
while F.alive and bgb<10 and not P.pauseAll do
if bgb>0 then
local egb,fgb,ggb=ab.xpFodder(Wfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Xfb)
Zfb,agb={},ggb
for hgb,igb in ipairs(egb)do
if not dgb[igb.uuid]then
table.insert(Zfb,igb)
end
end
if agb<=0 or#Zfb==0 then
break
end
end
local jgb={}
for kgb=1,math.min(ab.fuseBatch,#Zfb)do
table.insert(jgb,Zfb[kgb].uuid)
end
local lgb=tonumber((Wfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Xfb).xp)or 0
local mgb=U.now()
local ngb,ogb=F.request(Gje[3147],Gje[3148],O.fuseXpUnit,jgb)
if not ngb and(ogb==Gje[2086]or ogb==Gje[2085])then
if ogb==Gje[2085]or cgb>=3 then
break
end
cgb=cgb+1
task.wait(3.5)
continue
end
while U.now()-mgb<5 and(tonumber((Wfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Xfb).xp)or 0)<=lgb do
task.wait(0.1)
end
local pgb=tonumber((Wfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Xfb).xp)or 0
if pgb>lgb then
bgb=bgb+1
for qgb,rgb in ipairs(jgb)do
dgb[rgb]=true
end
cb.add(string.format(Gje[3149],#jgb,Yfb),#jgb,Gje[3150],string.format(Gje[3151],U.fmt(pgb-lgb)))
F.log(1,Gje[2516],string.format(Gje[3152],#jgb,Yfb,U.fmt(pgb-lgb),kb.level(Wfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Xfb)))
elseif#jgb>20 then
ab.fuseBatch=20
F.log(1,Gje[2516],string.format(Gje[3153],#jgb,tostring(F.gameSaid(mgb)or(ngb and ogb)or Gje[2546])))
else
local sgb=F.gameSaid(mgb)
ab.pickNote.autoFuseXp=Gje[3154]..tostring(sgb or(ngb and ogb)or Gje[2546])..Gje[3155]
F.log(1,Gje[2516],Gje[3156]..tostring(sgb or(ngb and ogb)or Gje[2546]))
F.backoff(Gje[3147],1800)
break
end
end
end
