ib.BONUS=1.5
ib.SLOW=1.4
function ib.boost(phb,qhb,rhb,shb)
if qhb<2 or rhb>=math.min(O.dangerReach,(shb or 1)*0.9)then
return
end
local thb=rhb<math.min(O.safeReach,(shb or 1)*0.75)
local uhb=0
for vhb,whb in ipairs(phb)do
if not whb.farm and not whb.train and whb.cost>0 then
uhb=math.max(uhb,whb.gain/whb.cost)
end
end
for xhb,yhb in ipairs(phb)do
if yhb.train==Gje[3203]or(yhb.train==Gje[3204]and thb)then
yhb.gain=math.max(yhb.gain,uhb*yhb.cost*1.05)
end
end
end
ib.HOLD_REACH=0.3
ib.ZONE=0.25
function ib.hold(zhb,Ahb,Bhb)
