end
return true,string.format(Gje[3205],math.floor(zhb*100+0.5))
end
function ib.same(Chb,Dhb)
if#Chb~= #Dhb then
return false
end
local Ehb={}
for Fhb,Ghb in ipairs(Chb)do
Ehb[Ghb]=true
end
for Hhb,Ihb in ipairs(Dhb)do
if not Ehb[Ihb]then
return false
end
end
return true
end
function ib.team()
local Jhb={}
for Khb,Lhb in ipairs(V.equipped())do
table.insert(Jhb,Lhb.uuid)
end
return Jhb
end
function ib.target()
local Mhb=N.session()
if not Mhb then
return nil
end
local Nhb,Ohb
local Phb=O.autoEvolve and O.evolveUnit~=Gje[933]and O.evolveUnit or nil
for Qhb,Rhb in ipairs(P.goals or{})do
local Shb,Thb=nil,0
for Uhb,Vhb in ipairs(Rhb.plans or{})do
if Vhb.takedown then
Shb=Vhb
else
Thb=Thb+1
end
end
local Whb=Shb and Rhb.intoTeam and(Rhb.pinned or not Rhb.unknown)and(not Phb or Rhb.uuid==Phb)and Mhb.collection:get_unit_by_uuid(Rhb.uuid)
if Whb then
local Xhb=tonumber(Shb.what==Gje[2663]and Whb.total_kills or Whb.total_takedowns)or 0
if Xhb<Shb.need then
local Yhb=(Thb==0 and 1000 or 0)+(tonumber(Rhb.tierRank)or 0)*10-Qhb*0.01
if not Nhb or Yhb>Ohb then
Nhb,Ohb={uuid=Rhb.uuid,id=Rhb.from,to=Rhb.to,what=Shb.what,have=Xhb,need=Shb.need},Yhb
end
end
end
end
return Nhb
end
function ib.realHave(Zhb)
local aib=N.session()
local bib=aib and aib.collection:get_unit_by_uuid(Zhb.uuid)
local cib=bib and tonumber(Zhb.what==Gje[2663]and bib.total_kills or bib.total_takedowns)or 0
return math.max(cib,Zhb.have+(Zhb.got or 0))
end
function ib.now()
if ib._at and U.now()-ib._at<10 then
return ib._t,ib._base
end
local dib=(P.train.on and P.train.on.base)or ib.team()
local eib=table.clone(dib)
table.sort(eib)
ib._t,ib._base,ib._at=ib.target(),table.concat(eib,Gje[2875]),U.now()
return ib._t,ib._base
end
function ib.valueFor(fib)
if not(O.trainTakedowns and O.goals)then
return 0,1
end
local gib=P.trainSim[fib.key]
if not(gib and gib.ok and os.time()-(gib.at or 0)<6*3600)then
return 0,1
end
local hib,iib=ib.now()
local jib={}
for kib,lib in ipairs(P.savedTeam or{})do
jib[kib]=lib
end
table.sort(jib)
if not(hib and gib.uuid==hib.uuid and(gib.base==iib or gib.base==table.concat(jib,Gje[2875])))or not ib.eligible(fib)then
return 0,1
end
local mib=ib.perRun(fib.key,hib.id)or 0
local nib=math.max(1,hib.need-hib.have)
return O.goalValue*math.min(mib,nib)/nib,gib.slow or 1
end
function ib.scan()
local oib=O.trainTakedowns and O.sim and ib.now()
if not oib then
return
end
local pib=(P.train.on and P.train.on.base)or ib.team()
for qib,rib in ipairs(pib)do
if rib==oib.uuid then
return
end
end
local sib,tib=0,0
for uib,vib in ipairs(W.lastScored or{})do
if sib>=3 or tib>=2 then
break
end
if ib.eligible(vib)then
local wib=P.trainSim[vib.key]
local xib=wib and wib.uuid==oib.uuid and os.time()-(wib.at or 0)<6*3600
local yib=ib.plan(vib,oib,pib)
if not xib then
tib=tib+1
end
if yib.ok then
sib=sib+1
end
end
end
local zib=ib.bestInfinite()
if zib then
ib.plan(zib,oib,pib)
end
end
function ib.bestInfinite()
local Aib,Bib
for Cib,Dib in ipairs(W.lastScored or{})do
if Dib.kind==Gje[2031]and ib.eligible(Dib)then
local Eib,Fib=P.train.real[Dib.key],Dib.rec or W.rec(Dib.key)
local Gib=(tonumber(Fib.timed)or 0)>0 and Fib.sec/Fib.timed/60 or 0
local Hib=(Eib and Eib.n>0 and Gib>0)and(Eib.sum/Eib.n)/Gib or 0
if Hib<=0 then
Hib=db.hiveTrainRate(Dib.key)or 0
end
if Hib>(Bib or 0)then
Aib,Bib=Dib,Hib
end
end
end
return Aib
end
function ib.ratio()
local Iib=P.train.cal
if not(Iib and(Iib.n or 0)>0 and(Iib.sim or 0)>0)then
return 1
end
return U.clamp(Iib.real/Iib.sim,0.05,2)
end
function ib.perRun(Jib,Kib)
local Lib=P.train.real[Jib]
if Lib and Lib.n>0 then
return Lib.sum/Lib.n,true
end
local Mib=db.hiveTrain(Jib,Kib)
if Mib then
return Mib,true
end
local Nib,Oib=0,0
local Pib=W.isInf(Jib)
for Qib,Rib in pairs(P.train.real)do
if W.isInf(Qib)==Pib then
Nib,Oib=Nib+Rib.sum,Oib+Rib.n
end
end
if Oib>0 then
return Nib/Oib,true
end
local Sib=P.trainSim[Jib]
