function gb.effFor(wEb)
local xEb,yEb=0,0
for zEb,AEb in pairs(P.simCal)do
local BEb,CEb=tonumber(AEb.eff),tonumber(AEb.n)or 0
if BEb and CEb>0 then
xEb=xEb+BEb*CEb
yEb=yEb+CEb
end
end
local DEb=yEb>0 and xEb/yEb or gb.PRIOR.eff
local EEb,FEb=tonumber(wEb and wEb.eff),tonumber(wEb and wEb.n)or 0
if not EEb then
return DEb
end
return(EEb*FEb+DEb*3)/(FEb+3)
end
