function jb.walletDiff(lkc,mkc)
local nkc={}
if mkc.gems~=lkc.gems then
table.insert(nkc,string.format(Gje[3964],mkc.gems-lkc.gems))
end
if mkc.gold~=lkc.gold then
table.insert(nkc,string.format(Gje[3965],mkc.gold-lkc.gold))
end
for okc,pkc in pairs(mkc.items)do
if pkc~=(lkc.items[okc]or 0)then
table.insert(nkc,string.format(Gje[3966],pkc-(lkc.items[okc]or 0),tostring(okc)))
end
end
for qkc,rkc in pairs(mkc.units)do
if not lkc.units[qkc]then
table.insert(nkc,Gje[3967]..V.name(rkc))
end
end
if mkc.unique~=lkc.unique then
table.insert(nkc,string.format(Gje[3968],mkc.unique-lkc.unique))
end
return#nkc>0 and table.concat(nkc,Gje[2124])or Gje[3969]
end
function jb.openChests(skc,tkc)
local ukc,vkc,wkc=jb.res(skc)
local xkc=jb.lives(skc)
local ykc=jb.cleared(skc)
if not(tkc or ykc>=jb.ROOMS or xkc<=1)then
jb.note(string.format(Gje[3970],ykc,vkc,wkc,jb.luck(skc)))
F.request(Gje[3956],Gje[3957])
return
end
local zkc,Akc,Bkc=0,0,0
local Ckc=tonumber(N.cur(Gje[2076]))or 0
local Dkc=jb.wallet()
for Ekc=1,vkc+wkc+4 do
local Fkc,Gkc,Hkc=jb.res(jb.data())
if Gkc+Hkc<=0 or Bkc>=2 then
break
end
local Ikc,Jkc
if Gkc>0 then
Ikc,Jkc=F.request(Gje[3971],Gje[3972])
else
Ikc,Jkc=F.request(Gje[3971],Gje[3972],true)
end
if Ikc and Jkc~=nil then
F.log(1,Gje[3940],Gje[3973]..(type(Jkc)==Gje[2012]and U.json(U.plain(Jkc)):sub(1,300)or tostring(Jkc)))
end
local Kkc=U.now()
while U.now()-Kkc<4 do
local Lkc,Mkc,Nkc=jb.res(jb.data())
if Mkc<Gkc or Nkc<Hkc then
break
end
task.wait(0.25)
end
local Okc,Pkc,Qkc=jb.res(jb.data())
if Pkc<Gkc then
zkc=zkc+(Gkc-Pkc)
Bkc=0
elseif Qkc<Hkc then
Akc=Akc+(Hkc-Qkc)
Bkc=0
else
Bkc=Bkc+1
end
task.wait(1)
if Pkc<Gkc or Qkc<Hkc then
local Rkc=jb.wallet()
local Skc=jb.walletDiff(Dkc,Rkc)
F.log(1,Gje[3940],(Qkc<Hkc and Gje[3974]or Gje[3973])..Skc)
P.dg.pay=P.dg.pay or{}
local Tkc={}
for Ukc,Vkc in pairs(Rkc.items)do
if Vkc~=(Dkc.items[Ukc]or 0)then
Tkc[Ukc]=Vkc-(Dkc.items[Ukc]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=Qkc<Hkc,gems=Rkc.gems-Dkc.gems,luck=jb.luck(skc),paid=Skc,items=Tkc})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
Dkc=Rkc
end
end
jb.note(string.format(Gje[3975],zkc,Akc,tkc and Gje[3976]or(xkc<=1 and Gje[3977]or Gje[3978]),jb.luck(skc),(tonumber(N.cur(Gje[2076]))or 0)-Ckc))
local Wkc,Xkc,Ykc=jb.res(jb.data())
if(tkc or ykc>=jb.ROOMS)and Xkc+Ykc>0 then
jb.note(string.format(Gje[3979],Xkc,Ykc))
W.rec(Gje[2731]).restUntil=os.time()+1800
return Gje[3980]
end
if not tkc then
F.request(Gje[3956],Gje[3957])
end
end
function jb.act(Zkc)
local _kc,alc=jb.state(Zkc)
jb.logState(Zkc,_kc)
if _kc==Gje[3939]then
return false
end
if _kc==Gje[3938]then
jb.note(string.format(Gje[3981],tostring(alc and alc.t)))
F.request(Gje[3956],Gje[3957])
return true
end
if _kc==Gje[2776]then
F.request(Gje[3982],Gje[3983])
jb.note(Gje[3984])
P.dg.lives,P.dg.lost,P.dg.bailed,P.dg.bails=5,{},{},{}
elseif _kc==Gje[3936]then
if jb.openChests(Zkc,true)==Gje[3980]then
return Gje[3980]
end
F.request(Gje[3956],Gje[3957])
local blc,clc,dlc=jb.res(jb.data())
table.insert(P.dg.runs,1,{at=os.time(),depth=jb.ROOMS,items=U.count(jb.items(Zkc)),left=clc+dlc})
while#P.dg.runs>10 do
table.remove(P.dg.runs)
end
jb.note(Gje[3985])
elseif _kc==Gje[3077]then
jb.shop(Zkc,alc)
elseif _kc==Gje[3891]then
jb.shrine(Zkc,alc)
elseif _kc==Gje[3937]then
if jb.openChests(Zkc,false)==Gje[3980]then
return Gje[3980]
end
end
return true
end
function jb.launch(elc)
local flc=jb.data()
if not flc then
