return false
end
local glc,hlc=F.request(Gje[3986],Gje[3987])
task.wait(2.5)
flc=jb.data()
if not(glc and flc and flc._started)then
F.log(1,Gje[3940],Gje[3988]..tostring(hlc)..Gje[3989])
W.rec(Gje[2731]).restUntil=os.time()+1800
F.backoff(Gje[3417],10)
