P.dg.roomK[soc]={k=uoc,n=(type(toc)==Gje[2012]and tonumber(toc.n)or 0)+1,at=os.time(),d=hoc.d}
bb.roomKUp=true
local voc={}
for woc,xoc in pairs(P.dg.roomK)do
table.insert(voc,{s=woc,at=type(xoc)==Gje[2012]and tonumber(xoc.at)or 0})
end
table.sort(voc,function(yoc,zoc)
return yoc.at>zoc.at
end)
for Aoc=31,#voc do
P.dg.roomK[voc[Aoc].s]=nil
end
F.log(1,Gje[3940],string.format(Gje[4052],tostring(hoc.d),roc,uoc))
end
