function bb.buildPath()
bb.samples={}
local bpc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not bpc then
return
end
for cpc,dpc in pairs(bpc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[cpc.Name])then
local epc={}
for fpc,gpc in ipairs(dpc.points or{})do
table.insert(epc,gpc.part.Position)
end
local hpc=0
for ipc=2,#epc do
hpc=hpc+(epc[ipc]-epc[ipc-1]).Magnitude
end
local jpc=0
for kpc=2,#epc do
local lpc,mpc=epc[kpc-1],epc[kpc]
local npc=(mpc-lpc).Magnitude
local opc=math.max(1,math.floor(npc/2))
for ppc=0,opc-1 do
local qpc=lpc:Lerp(mpc,ppc/opc)
table.insert(bb.samples,{pos=qpc,prog=(jpc+npc*ppc/opc)/math.max(1,hpc),lane=cpc.Name})
end
jpc=jpc+npc
end
if epc[#epc]then
table.insert(bb.samples,{pos=epc[#epc],prog=1,lane=cpc.Name})
end
end
end
pcall(bb.readHidden,bpc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local rpc=tonumber(bb.ld and bb.ld._portal_lanes)
local spc=gb.laneList(bb.samples)
if rpc and rpc>=1 and spc and#spc>rpc then
bb.laneWant=rpc
end
bb.laneTotal=spc and#spc or 1
bb.countLanes()
end
function bb.readHidden(tpc)
local upc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(upc)~=Gje[2012]or not next(upc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local vpc
for wpc,xpc in pairs(tpc)do
if upc[wpc.Name]and type(xpc.points)==Gje[2012]and#xpc.points>=2 then
local ypc={}
for zpc,Apc in ipairs(xpc.points)do
ypc[zpc]=U.flat(Apc.part.Position)
end
local Bpc={}
for Cpc,Dpc in ipairs(bb.samples)do
local Epc=tostring(Dpc.lane)
Bpc[Epc]=Bpc[Epc]or{}
table.insert(Bpc[Epc],Dpc)
end
local Fpc,Gpc
for Hpc,Ipc in pairs(Bpc)do
local Jpc=0
for Kpc=1,#ypc,math.max(1,math.floor(#ypc/20))do
local Lpc=math.huge
for Mpc,Npc in ipairs(Ipc)do
local Opc=(U.flat(Npc.pos)-ypc[Kpc]).Magnitude
if Opc<Lpc then
Lpc=Opc
end
end
Jpc=Jpc+Lpc
end
if not Gpc or Jpc<Gpc then
Fpc,Gpc=Hpc,Jpc
end
end
local Ppc,Qpc,Rpc,Spc,Tpc,Upc={},nil,nil,nil,0,0
for Vpc,Wpc in ipairs(ypc)do
local Xpc,Ypc=nil,math.huge
for Zpc,_pc in ipairs(Bpc[Fpc])do
local aqc=(U.flat(_pc.pos)-Wpc).Magnitude
if aqc<Ypc then
Ypc,Xpc=aqc,_pc.prog
end
end
Upc=math.max(Upc,Ypc)
if Rpc then
local bqc=Xpc-Rpc
local cqc=(bqc>0.002 and 1)or(bqc< -0.002 and-1)or Spc
if Spc and cqc and cqc~=Spc then
table.insert(Ppc,math.floor(Rpc*1000+0.5)/1000)
end
Spc,Tpc=cqc or Spc,Tpc+math.abs(bqc)
else
Qpc=Xpc
end
Rpc=Xpc
if Vpc%50==0 then
task.wait()
end
end
if Rpc and Upc<=8 then
table.insert(Ppc,math.floor(Rpc*1000+0.5)/1000)
vpc=vpc or{}
vpc[wpc.Name]={from=math.floor((Qpc or 0)*1000+0.5)/1000,len=math.floor(Tpc*1000+0.5)/1000,turns=Ppc,road=Fpc}
end
end
end
if not vpc then
return
end
local dqc=bb.ld.map
P.maps[dqc]=P.maps[dqc]or{}
local eqc=P.maps[dqc].hidden
P.maps[dqc].hidden=vpc
if type(eqc)~=Gje[2012]then
for fqc,gqc in pairs(vpc)do
F.log(1,Gje[2680],string.format(Gje[4068],fqc,gqc.len,tostring(gqc.road),math.floor((#gqc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local hqc,iqc,jqc={},0,0
for kqc,lqc in ipairs(bb.samples)do
local mqc=tostring(lqc.lane)
if not hqc[mqc]then
iqc=iqc+1
end
hqc[mqc]=(hqc[mqc]or 0)+1
jqc=jqc+1
end
bb.laneCount={n=iqc,by=hqc,avg=iqc>0 and jqc/iqc or 1}
if iqc>=2 then
local nqc,oqc=pcall(gb.laneSep,bb.samples)
local pqc=P.maps[bb.mapKey()]
if nqc and oqc and type(pqc)==Gje[2012]then
pqc.sep=oqc
end
end
end
bb.LANE_WAIT=3
function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local qqc,rqc={},0
for sqc,tqc in ipairs(workspace._UNITS:GetChildren())do
local uqc=tqc:FindFirstChild(Gje[2075])
if uqc and uqc:FindFirstChild(Gje[4069])and uqc.player.Value==nil and uqc:FindFirstChild(Gje[4070])and tqc:FindFirstChild(Gje[3268])then
local vqc=tostring(uqc.lane.Value)
if not qqc[vqc]then
qqc[vqc]=true
rqc=rqc+1
end
end
end
if rqc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,Gje[2680],Gje[4071])
return true
end
return false
end
bb.laneFirst=bb.laneFirst or U.now()
if rqc<bb.laneWant and U.now()-bb.laneFirst<bb.LANE_WAIT then
return false
end
local wqc,xqc={},{}
for yqc,zqc in ipairs(bb.samples)do
if qqc[tostring(zqc.lane)]then
table.insert(wqc,zqc)
end
end
if#wqc==0 then
bb.laneWant=nil
return true
end
for Aqc in pairs(qqc)do
table.insert(xqc,Aqc)
end
table.sort(xqc)
bb.samples,bb.laneCut=wqc,table.concat(xqc,Gje[2326])
bb.countLanes()
local Bqc,Cqc=pcall(bb.buildCandidates)
if not Bqc then
F.log(1,Gje[2398],Gje[4072]..tostring(Cqc))
end
F.log(1,Gje[2680],string.format(Gje[4073],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local Dqc,Eqc=pcall(bb.planSpots)
bb.planning=nil
if not Dqc then
F.log(1,Gje[2398],Gje[4074]..tostring(Eqc))
end
end)
end
return true
end
function bb.buildWaves()
local Fqc=bb.ld
local Gqc=Fqc and Fqc._dungeon and type(Fqc._override_waves)==Gje[2012]and Fqc._override_waves or nil
local Hqc=Fqc and N.Waves[(Gqc and Gqc.template)or Fqc.waves or Fqc.id]
local Iqc
if type(Hqc)==Gje[2012]then
Iqc=Hqc.override_waves or Hqc.waves
if not Iqc and Hqc.template and N.Waves[Hqc.template]then
Iqc=N.Waves[Hqc.template].waves or N.Waves[Hqc.template].override_waves
end
end
bb.waveList=U.list(Iqc)
bb.infinite=Fqc and(Fqc._gamemode==Gje[2031]or Fqc.infinite)and gb.unbound(Fqc)or false
if bb.infinite then
bb.waveList={}
bb.total=math.max(30,math.floor(W.infReach(bb.key)+0.5))
return
end
bb.total=(Fqc and type(Fqc._dungeon)==Gje[2012]and 15)or tonumber(Fqc and Fqc._override_infinite_bound_waves)or gb.boundEnd(Fqc,#bb.waveList,bb.key)or(#bb.waveList>0 and#bb.waveList)or 15
end
function bb.infExtend()
if bb.infinite and bb.wave()+5>bb.total then
bb.total=bb.wave()+10
end
end
function bb.infWave(Jqc)
bb.infWaveAt=bb.infWaveAt or{}
bb.infWaveAt[Jqc]=bb.infWaveAt[Jqc]or U.now()
bb.infExtend()
if O.trainLeave and not bb.stopping then
local Kqc,Lqc=pcall(bb.trainLeave,Jqc)
if not Kqc then
F.log(1,Gje[2398],Gje[4075]..tostring(Lqc))
end
end
if O.infiniteStop and not bb.stopping and ab.partyRole()~=Gje[3562]and bb.kind~=Gje[2467]then
local Mqc,Nqc=pcall(bb.infStop,Jqc)
if not Mqc then
F.log(1,Gje[2398],Gje[4076]..tostring(Nqc))
end
end
local Oqc=W.infTier(Jqc-1)
if Oqc<=0 or Oqc==bb.infTierSeen then
return
end
bb.infTierSeen=Oqc
task.delay(5,function()
if not F.alive then
return
end
local Pqc=N.prof()
local Qqc=Pqc and Pqc.daily_infinite_reward_claims and Pqc.daily_infinite_reward_claims[bb.ld.id]
local Rqc=type(Qqc)==Gje[2012]and(tonumber(Qqc.highest_claimed_wave)or 0)>=Oqc and os.time()-(tonumber(Qqc.highest_claim_time)or 0)<900
if Rqc then
P.infLive=true
end
F.log(1,Gje[2680],string.format(Gje[4077],Oqc,Rqc and Gje[4078]or Gje[4079]))
end)
end
function bb.infStop(Sqc)
local Tqc=0
for Uqc,Vqc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
Tqc=math.max(Tqc,tonumber(Vqc.wave)or 0)
end
if Tqc<=0 or Sqc<=Tqc+1 then
return
end
local Wqc=P.train.on
if bb.trainee and Wqc and Wqc.have+(Wqc.got or 0)+(bb.trainTk or 0)<Wqc.need then
return
end
if not ab.every(Gje[4080],60)then
return
end
local Xqc=W.rec(bb.key)
local Yqc=tonumber(Xqc.timed)or 0
local Zqc=W.INF_PAY
local _qc
if Sqc>=(Zqc.cap+Zqc.less)/Zqc.per then
_qc=0
else
local arc=bb.infWaveAt or{}
local brc,crc=arc[Sqc],arc[Sqc-5]
if brc and crc and brc>crc then
_qc=Zqc.per*5/((brc-crc)/60)
end
if not _qc then
_qc=(Yqc>0 and(Xqc.sec or 0)>0)and math.max(0.5,(Xqc.gems or 0)/(Xqc.sec/60))or 2.5
end
end
local drc=pcall(W.pick)
local erc
for frc,grc in ipairs(drc and W.lastScored or{})do
if grc.kind~=Gje[2031]and(not erc or(grc.score or 0)>(erc.score or 0))then
erc=grc
end
end
if not erc or(erc.score or 0)<=_qc then
return
end
bb.stopping=true
F.log(1,Gje[2680],string.format(Gje[4081],Sqc,_qc,erc.score,erc.label))
bb.sellAll()
end
function bb.trainLeave(hrc)
local irc=P.train.on
if not(bb.infinite and bb.trainee and irc)then
return
end
bb.trainCount()
local jrc=irc.have+(irc.got or 0)+(bb.trainTk or 0)
if jrc<irc.need then
return
end
local krc,lrc,mrc=pcall(W.infDaily,N.prof(),bb.ld.id,(W.infReach(bb.key)))
if krc and(lrc or 0)>0 and mrc>0 and hrc<=mrc then
F.status(Gje[3232],string.format(Gje[4082],V.name(irc.id),irc.what,mrc))
return
end
bb.stopping=true
F.log(1,Gje[2680],string.format(Gje[4083],V.name(irc.id),irc.what,U.fmt(jrc),U.fmt(irc.need),hrc))
bb.sellAll()
end
function bb.sellAll()
task.spawn(function()
local nrc={}
for orc,prc in ipairs(bb.mine or{})do
local qrc=prc:FindFirstChild(Gje[2075])
local rrc=qrc and qrc:FindFirstChild(Gje[2389])and N.Units[qrc.id.Value]
if not(rrc and rrc.unsellable)then
table.insert(nrc,prc)
end
end
local function trc(urc)
local vrc=urc:FindFirstChild(Gje[2075])
return vrc and vrc:FindFirstChild(Gje[2389])and V.isFarm(vrc.id.Value)or false
end
table.sort(nrc,function(wrc,xrc)
return(trc(wrc)and 1 or 0)<(trc(xrc)and 1 or 0)
end)
local yrc={}
for zrc=1,2 do
local Arc={}
for Brc,Crc in ipairs(zrc==1 and nrc or yrc)do
if not F.alive or bb.finished then
return
end
if Crc.Parent and Crc.Parent.Name==Gje[4084]then
local Drc,Erc=F.request(Gje[2194],Gje[2392],Crc)
if Erc~=true then
table.insert(Arc,Crc)
end
task.wait(1.3)
end
end
yrc=Arc
end
if#yrc>0 then
local Frc={}
for Grc,Hrc in ipairs(yrc)do
table.insert(Frc,Hrc.Name)
end
F.log(1,Gje[2680],Gje[4085]..table.concat(Frc,Gje[2124])..Gje[4086])
end
end)
end
function bb.waveReward(Irc)
