end
if not N.PC.is_valid_raycast_hit(rtc.Instance,ptc)then
return nil
end
local stc=rtc.Position
if bb.blockedSpot(stc)then
return nil
end
local ttc=(tonumber(ptc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(ttc*2,2.5,ttc*2)
bb.probe.CFrame=CFrame.new(stc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local utc=U.flat(stc)
for vtc,wtc in ipairs(bb.mine or{})do
local xtc=wtc:FindFirstChild(Gje[4104])
local ytc=xtc and xtc.Position or wtc:GetPivot().Position
local ztc=xtc and math.max(xtc.Size.X,xtc.Size.Z)/2 or 1.5
if(utc-U.flat(ytc)).Magnitude<ttc+ztc then
return nil
end
end
if not qtc then
for Atc,Btc in ipairs(bb.blockers())do
if(utc-Btc.p).Magnitude<ttc+Btc.r then
return nil
end
end
end
return stc
end
function bb.buildCandidates()
