if Gtc.Magnitude<0.01 then
Gtc=Vector3 .new(1,0,0)
end
Gtc=Gtc.Unit
local Htc=Vector3 .new(-Gtc.Z,0,Gtc.X)
for Itc,Jtc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for Ktc,Ltc in ipairs({1,-1})do
local Mtc=Etc.pos+Htc*Jtc*Ltc
