function bb.coverage(Otc,Ptc)
local Qtc={}
for Rtc,Stc in ipairs(Otc)do
local Ttc=Stc._stats
if not V.isFarm(Ttc.id.Value)and Ttc:FindFirstChild(Gje[2264])then
table.insert(Qtc,{p=U.flat(Stc:GetPivot().Position),r=Ttc.range.Value*(V.SUMMONER[Ttc.id.Value]and V.SUMMONER[Ttc.id.Value].reach or 1),air=bb.canAir(Stc)})
end
end
local Utc,Vtc=0,0
if#Qtc>0 then
for Wtc,Xtc in ipairs(bb.samples)do
if Xtc.prog>Vtc then
local Ytc=U.flat(Xtc.pos)
for Ztc,_tc in ipairs(Qtc)do
if(Ytc-_tc.p).Magnitude<=_tc.r then
if Xtc.prog>Utc then
Utc=Xtc.prog
end
if _tc.air then
Vtc=Xtc.prog
break
end
end
end
end
end
end
local auc,buc={},bb.laneCount
if buc and buc.n>=2 and#Qtc>0 then
local cuc={}
for duc,euc in ipairs(bb.samples)do
local fuc=U.flat(euc.pos)
for guc,huc in ipairs(Qtc)do
if(fuc-huc.p).Magnitude<=huc.r then
local iuc=tostring(euc.lane)
cuc[iuc]=(cuc[iuc]or 0)+1
if euc.prog>(auc[iuc]or 0)then
auc[iuc]=euc.prog
end
break
end
end
end
local juc,kuc={},0
for luc,muc in pairs(buc.by)do
juc[luc]=(cuc[luc]or 0)/math.max(1,muc)
kuc=math.max(kuc,juc[luc])
end
bb.laneW={}
for nuc,ouc in pairs(buc.by)do
bb.laneW[nuc]=(buc.avg/math.max(1,ouc))*(1+1.5*(kuc>0 and(1-juc[nuc]/kuc)or 0))
end
bb.laneFrac=juc
else
bb.laneW,bb.laneFrac=nil,nil
end
local puc,quc,ruc
if#Qtc>0 then
for suc,tuc in ipairs(Ptc)do
local uuc=(bb.laneW and tuc.lane)and(auc[tostring(tuc.lane)]or 0)or Utc
if tuc.hp>0 and tuc.prog>uuc+0.02 and tuc.prog>(puc or 0)then
puc,ruc=tuc.prog,bb.laneW and tuc.lane or nil
end
if tuc.hp>0 and tuc.fly and tuc.prog>Vtc+0.02 then
quc=true
end
end
end
local vuc= #Qtc>0 and(bb.pressure or 0)>=Utc-0.08
return{covEnd=Utc,airEnd=Vtc,leak=puc,leakLane=ruc,covL=auc,airLeak=quc,push=vuc,units= #Qtc}
end
function bb.needLastLine(wuc)
