V._airFrom={}
function V.airFrom(Kuc)
local Luc=V._airFrom[Kuc]
if Luc~=nil then
return Luc or nil
end
local Muc=N.Units[Kuc]
if Muc and(Muc.hill_unit or Muc.hybrid_placement or V.SUMMONER[Kuc])then
V._airFrom[Kuc]=0
return 0
end
local Nuc=V.rows(Kuc)
if not(Nuc and Nuc.max)then
return bb.cardAir(Kuc)and 0 or nil
end
local Ouc=false
for Puc=0,Nuc.max do
local Quc=Nuc[Puc]and Nuc[Puc].atk
if Quc and N.Attacks[Quc]and N.Attacks[Quc].targets_flying then
Ouc=Puc
break
end
end
if Ouc==false and bb.cardAir(Kuc)then
Ouc=0
end
V._airFrom[Kuc]=Ouc
return Ouc or nil
end
function bb.cardAir(Ruc)
local Suc=N.Units[Ruc]
if not Suc then
return false
end
if Suc.hill_unit or Suc.hybrid_placement then
return true
end
local Tuc=V.field(Ruc,Gje[2117])or V.field(Ruc,Gje[2116])
return Tuc and N.Attacks[Tuc]and N.Attacks[Tuc].targets_flying and true or false
end
function bb.airShare()
