function bb.cover(cwc,dwc,ewc,fwc,gwc)
local hwc=0
local iwc=U.flat(cwc)
local jwc=ewc and P.maps[bb.mapKey()]and P.maps[bb.mapKey()].dens
local kwc=bb.laneW
for lwc,mwc in ipairs(gwc and bb.samples or bb.hurtSamples())do
if(U.flat(mwc.pos)-iwc).Magnitude<=dwc then
local nwc=1
if jwc then
nwc=0.15+0.85*(tonumber(jwc[math.min(gb.BINS,math.floor(mwc.prog*gb.BINS)+1)])or 0)
end
if kwc then
nwc=nwc*(kwc[tostring(mwc.lane)]or 1)
end
if fwc then
if fwc.leak and mwc.prog>=fwc.leak-0.01 and(not fwc.leakLane or tostring(mwc.lane)==fwc.leakLane)then
nwc=nwc+3
elseif fwc.push and mwc.prog>fwc.covEnd then
nwc=nwc+0.6
end
end
hwc=hwc+nwc
end
end
return hwc
end
