bb.STUDY_INF_WAIT=240
function bb.validOpen(JKc,KKc)
local LKc=N.PC.raycast(JKc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not LKc then
return nil
end
if not N.PC.is_valid_raycast_hit(LKc.Instance,KKc)then
return nil
end
local MKc=LKc.Position
if bb.blockedSpot(MKc)then
return nil
end
local NKc=(tonumber(KKc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(NKc*2,2.5,NKc*2)
bb.probe.CFrame=CFrame.new(MKc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return MKc
end
