if not V.isFarm(TKc.id)and not V.allyBuff(TKc.id)and TKc.uuid~=bb.trainee and V.rows(TKc.id)then
local UKc,VKc=pcall(V.score,TKc.u,bb.mod)
table.insert(RKc,{e=TKc,id=TKc.id,sc=UKc and VKc or 0})
end
end
if#RKc==0 then
