return CLc.kills and string.format(Gje[4186],math.floor((tonumber(ELc)or 0)+0.5))or string.format(Gje[4242],tonumber(FLc)or 0,tonumber(CLc.hp)or 1)
end
return string.format(Gje[4243],tostring(CLc.label),tonumber(CLc.n)or 0,tonumber(CLc.run)or 0,DLc(CLc.bestKills,CLc.bestWave),DLc(CLc.baseKills,CLc.baseWave),(CLc.better or 0)>0 and Gje[4244]or Gje[933])
end
function bb.bookSave(GLc,HLc,ILc,JLc)
P.mapBook=type(P.mapBook)==Gje[2012]and P.mapBook or{}
local KLc={}
for LLc,MLc in pairs(ILc.spots or{})do
KLc[LLc]={math.floor(MLc.X*10+0.5)/10,math.floor(MLc.Y*10+0.5)/10,math.floor(MLc.Z*10+0.5)/10}
end
P.mapBook[HLc.key]={spots=KLc,style=HLc.base.style,hp=JLc.hp,n=JLc.n,kills=ILc.kills and math.floor(ILc.kills+0.5)or nil,wave=ILc.wave and math.floor(ILc.wave*10+0.5)/10 or nil,base=JLc.baseWave and math.floor(JLc.baseWave*10+0.5)/10 or nil,label=JLc.label,map=GLc.map,killScore=JLc.kills,at=os.time()}
local NLc={}
for OLc,PLc in pairs(P.mapBook)do
table.insert(NLc,{k=OLc,at=type(PLc)==Gje[2012]and tonumber(PLc.at)or 0})
end
if#NLc>bb.BOOK_MAX then
table.sort(NLc,function(QLc,RLc)
return QLc.at>RLc.at
end)
for SLc=bb.BOOK_MAX+1,#NLc do
P.mapBook[NLc[SLc].k]=nil
end
end
F.saveSoon()
end
function bb.studyEnd(TLc,ULc,VLc)
if type(TLc)~=Gje[2012]or TLc.ended then
return
end
TLc.ended=true
if VLc and ULc then
local WLc=bb.bookFor(ULc.info)
if WLc then
WLc.n=TLc.n
F.saveSoon()
elseif TLc.run>0 then
pcall(bb.bookSave,ULc.info,ULc,VLc,TLc)
end
end
if TLc.run>0 then
F.log(1,Gje[2765],bb.studyWords(TLc))
end
end
