bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
function bb.layoutRecFor(oMc,pMc)
local qMc=bb.bookKey(oMc)
P.layoutRec=type(P.layoutRec)==Gje[2012]and P.layoutRec or{}
local rMc=P.layoutRec[qMc]
if type(rMc)~=Gje[2012]then
if not pMc then
return nil
end
rMc={at=os.time()}
P.layoutRec[qMc]=rMc
if U.count(P.layoutRec)>80 then
local sMc,tMc
for uMc,vMc in pairs(P.layoutRec)do
local wMc=type(vMc)==Gje[2012]and tonumber(vMc.at)or 0
if not tMc or wMc<tMc then
sMc,tMc=uMc,wMc
end
end
P.layoutRec[sMc]=nil
end
end
return rMc
end
function bb.layoutAdd(xMc,yMc,zMc,AMc,BMc)
xMc.runs,xMc.wins=(tonumber(xMc.runs)or 0)+1,(tonumber(xMc.wins)or 0)+(yMc and 1 or 0)
xMc.sec,xMc.wave=type(xMc.sec)==Gje[2012]and xMc.sec or{},type(xMc.wave)==Gje[2012]and xMc.wave or{}
if yMc and tonumber(zMc)then
table.insert(xMc.sec,math.floor(zMc+0.5))
end
table.insert(xMc.wave,tonumber(AMc)or 0)
if tonumber(BMc)then
xMc.kills=type(xMc.kills)==Gje[2012]and xMc.kills or{}
table.insert(xMc.kills,math.floor(tonumber(BMc)))
while#xMc.kills>bb.LAYOUT_KEEP do
table.remove(xMc.kills,1)
end
end
while#xMc.sec>bb.LAYOUT_KEEP do
table.remove(xMc.sec,1)
end
while#xMc.wave>bb.LAYOUT_KEEP do
table.remove(xMc.wave,1)
end
end
function bb.layoutJudge(CMc,DMc,EMc,FMc)
local GMc,HMc=tonumber(CMc and CMc.runs)or 0,tonumber(DMc and DMc.runs)or 0
if GMc<1 or HMc<bb.LAYOUT_CONTROL then
return nil
end
if FMc and type(CMc.kills)==Gje[2012]and type(DMc.kills)==Gje[2012]and#CMc.kills>=1 and#DMc.kills>=bb.LAYOUT_CONTROL then
local IMc,JMc=bb.labMedian(CMc.kills),bb.labMedian(DMc.kills)
if IMc and JMc and IMc<JMc*0.97 and(#CMc.kills>=2 or IMc<JMc*0.85)then
return string.format(Gje[4250],IMc,JMc)
end
return nil
end
local KMc,LMc=(tonumber(CMc.wins)or 0)/GMc,(tonumber(DMc.wins)or 0)/HMc
if not EMc and LMc>=0.5 then
if KMc+0.25<LMc and(GMc>=2 or(KMc==0 and LMc>=0.9 and HMc>=3))then
return string.format(Gje[4251],tonumber(CMc.wins)or 0,GMc,GMc==1 and Gje[933]or Gje[1860],tonumber(DMc.wins)or 0,HMc)
end
local MMc,NMc=bb.labMedian(CMc.sec),bb.labMedian(DMc.sec)
if MMc and NMc and MMc>NMc*1.10 and(#CMc.sec>=2 or MMc>NMc*1.25)then
return string.format(Gje[4252],math.floor(MMc/60),MMc%60,math.floor(NMc/60),NMc%60)
end
return nil
end
local OMc,PMc=bb.labMedian(CMc.wave),bb.labMedian(DMc.wave)
if OMc and PMc and OMc<PMc-math.max(1,PMc*0.03)and(GMc>=2 or OMc<PMc*0.85)then
return string.format(Gje[4253],OMc,PMc)
end
return nil
end
function bb.layoutResult(QMc,RMc)
local SMc=bb.info
local TMc=bb.layoutSrc
if not(SMc and TMc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not SMc.timeLimit then
return
end
local UMc=bb.wave()
local VMc=bb.layoutRecFor(SMc,true)
VMc.at=os.time()
local WMc=SMc.timeLimit~=nil
local XMc=SMc.killScore and true or nil
local YMc=XMc and(bb.killsEnd or bb.realKills())or nil
if TMc==Gje[4223]then
local ZMc=bb.bookFor(SMc)
if not ZMc then
return
end
ZMc.real=type(ZMc.real)==Gje[2012]and ZMc.real or{}
bb.layoutAdd(ZMc.real,QMc,RMc,UMc,YMc)
local _Mc=ZMc.aside==nil and bb.layoutJudge(ZMc.real,VMc.own,WMc,XMc)or nil
if _Mc then
ZMc.aside={at=os.time(),why=_Mc}
F.log(1,Gje[4169],string.format(Gje[4254],_Mc))
end
else
VMc[TMc]=type(VMc[TMc])==Gje[2012]and VMc[TMc]or{}
local aNc=VMc[TMc]
bb.layoutAdd(aNc,QMc,RMc,UMc,YMc)
if TMc==Gje[3603]and aNc.aside==nil then
local bNc=bb.layoutJudge(aNc,VMc.own,WMc,XMc)
if bNc then
aNc.aside,aNc.why=os.time(),bNc
F.log(1,Gje[4169],string.format(Gje[4255],bNc))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={Gje[4256],Gje[4257],Gje[4258],Gje[4259]}
function bb.controlSpot(cNc,dNc)
if not bb.killZone()then
return nil
end
local eNc=gb.holds
if not eNc(cNc.id)or V.toggleOf(cNc.id)then
return nil
end
local fNc,gNc,hNc,iNc=1,0,0,{}
local jNc=bb.hurtSamples()
for kNc,lNc in ipairs(bb.mine or{})do
local mNc=lNc._stats
local nNc=mNc.id.Value
if mNc:FindFirstChild(Gje[2264])and not V.isFarm(nNc)and not V.allyBuff(nNc)then
local oNc,pNc=U.flat(lNc:GetPivot().Position),mNc.range.Value
if eNc(nNc)and not V.toggleOf(nNc)then
hNc=hNc+1
table.insert(iNc,{p=oNc,r=pNc})
else
for qNc,rNc in ipairs(jNc)do
if(U.flat(rNc.pos)-oNc).Magnitude<=pNc then
fNc,gNc=math.min(fNc,rNc.prog),math.max(gNc,rNc.prog)
end
end
end
end
end
if gNc<=fNc then
fNc,gNc=0.75,0.98
end
local sNc=(dNc or hNc)+1
local tNc=({fNc,gNc,(fNc+gNc)/2,fNc-(gNc-fNc)/2})[sNc]
if not tNc then
return nil
end
local uNc=V.range(cNc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local vNc={}
for wNc,xNc in ipairs(bb.cands)do
local yNc,zNc,ANc=U.flat(xNc),0,0
for BNc,CNc in ipairs(jNc)do
if(U.flat(CNc.pos)-yNc).Magnitude<=uNc then
ANc=ANc+1
if math.abs(CNc.prog-tNc)<=0.05 then
zNc=zNc+1
local DNc=U.flat(CNc.pos)
for ENc,FNc in ipairs(iNc)do
if(DNc-FNc.p).Magnitude<=FNc.r then
zNc=zNc-0.5
break
end
end
end
end
end
if zNc>0 then
table.insert(vNc,{pos=xNc,sc=zNc,cov=ANc})
end
if wNc%60==0 then
task.wait()
end
end
table.sort(vNc,function(GNc,HNc)
return GNc.sc>HNc.sc
end)
for INc,JNc in ipairs(vNc)do
local KNc=bb.valid(JNc.pos,cNc.data)
if KNc then
F.log(1,Gje[4108],string.format(Gje[4260],V.name(cNc.id),bb.CONTROL_WORDS[sNc],math.floor(tNc*100+0.5)))
return KNc,JNc.cov,tNc
end
if INc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(LNc)
local MNc,NNc=gb.holds(LNc.id)
if not MNc then
return nil
end
if V.killFed(LNc.id)then
return nil
end
local ONc,PNc={},0
for QNc,RNc in ipairs(bb.mine or{})do
local SNc=RNc._stats
local TNc=SNc.id.Value
if SNc:FindFirstChild(Gje[2264])and not V.isFarm(TNc)and not V.allyBuff(TNc)and TNc~=LNc.id then
local UNc,VNc=pcall(bb.liveDps,RNc,TNc)
VNc=UNc and tonumber(VNc)or 0
if VNc>0 then
table.insert(ONc,{p=U.flat(RNc:GetPivot().Position),r=SNc.range.Value,d=VNc})
PNc=PNc+VNc
end
end
end
if#ONc==0 or PNc<=0 then
return nil
end
local WNc=bb.hurtSamples()
local XNc={}
for YNc,ZNc in ipairs(WNc)do
local _Nc,aOc=U.flat(ZNc.pos),0
for bOc,cOc in ipairs(ONc)do
if(_Nc-cOc.p).Magnitude<=cOc.r then
aOc=aOc+cOc.d
end
end
XNc[YNc]=aOc/PNc
end
local dOc=V.range(LNc.u,math.min(tonumber(NNc)or 0,3,V.rows(LNc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local eOc,fOc,gOc
for hOc,iOc in ipairs(bb.cands)do
local jOc,kOc,lOc=U.flat(iOc),0,0
for mOc,nOc in ipairs(WNc)do
if(U.flat(nOc.pos)-jOc).Magnitude<=dOc then
kOc=kOc+XNc[mOc]
lOc=lOc+1
end
end
if kOc>0 and(not fOc or kOc>fOc)then
local oOc=bb.valid(iOc,LNc.data)
if oOc then
eOc,fOc,gOc=oOc,kOc,lOc
end
end
if hOc%40==0 then
task.wait()
end
end
if not eOc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[LNc.id]then
bb.holdSaid[LNc.id]=true
F.log(1,Gje[4108],string.format(Gje[4261],V.name(LNc.id)))
end
return eOc,gOc or 0
end
