function bb.place(sRc,tRc)
local uRc=V.isFarm(sRc.id)
local vRc,wRc=bb.bestSpot(sRc,uRc or V.idol(sRc.id),(bb.trainee~=nil and sRc.uuid==bb.trainee)or V.ENTRY[sRc.id]==true or(bb.studyEntry==true and sRc.id==bb.trialId))
