bb.noSpot[sRc.uuid]=(bb.noSpot[sRc.uuid]or 0)+1
F.status(Gje[4172],Gje[4263]..V.name(sRc.id))
return false
end
local xRc=bb.money()
local yRc=P.caps[sRc.uuid]and bb.count(sRc.uuid)or nil
local zRc,ARc=F.request(Gje[4264],Gje[4265],sRc.uuid,N.Util.CFramePLV(vRc,bb.lookAt(vRc)))
if zRc and ARc then
if yRc and yRc>=(tonumber(P.caps[sRc.uuid])or math.huge)then
F.log(1,Gje[4108],string.format(Gje[4266],V.name(sRc.id),tostring(P.caps[sRc.uuid])))
P.caps[sRc.uuid],P.capsAt[sRc.uuid]=nil,nil
F.saveSoon()
end
bb.spent=bb.spent+(sRc.data.cost or 0)
table.insert(bb.actions,string.format(Gje[4267],V.name(sRc.id)))
F.log(1,Gje[4108],string.format(Gje[4268],V.name(sRc.id),bb.spotKey(vRc),wRc,tRc))
bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=sRc.id,x=math.floor(vRc.X),z=math.floor(vRc.Z),cover=math.floor((wRc or 0)+0.5),why=tostring(tRc):sub(1,90)})
F.status(Gje[4172],string.format(Gje[4269],V.name(sRc.id),tRc))
bb.placedAt=bb.placedAt or{}
bb.placedAt[sRc.uuid]=(bb.placedAt[sRc.uuid]or 0)+1
return true
end
if xRc>=(sRc.data.cost or 0)and bb.random then
