function bb.measure()
local LRc,MRc=bb.calRun,bb.info
if not(LRc and MRc)then
return
end
pcall(bb.sampleHelpers)
local NRc=U.now()
local ORc=bb.wave()
local PRc=bb.money()
if not LRc.start and PRc>0 and#bb.mine==0 then
LRc.start=PRc
end
if ORc~=LRc.lastW then
if bb.trialId and ORc>0 then
bb.trialTrace=bb.trialTrace or{}
local QRc,RRc,SRc,TRc=0,{},0,0
for URc,VRc in ipairs(bb.mine)do
local WRc=VRc._stats
if WRc.id.Value==bb.trialId then
QRc=QRc+1
table.insert(RRc,tostring(WRc.upgrade.Value))
elseif not V.isFarm(WRc.id.Value)then
TRc=TRc+1
end
end
pcall(bb.sampleHelpers,true)
for XRc,YRc in pairs(bb.ownDealt)do
if YRc.id==bb.trialId then
SRc=SRc+YRc.v
end
end
local ZRc=0
for _Rc,aSc in pairs(bb.helperDealt)do
if aSc.owner==bb.trialId then
ZRc=ZRc+aSc.v
end
end
table.insert(bb.trialTrace,string.format(Gje[4275],ORc,NRc-(bb.startT or NRc),PRc,table.concat(RRc,Gje[2875]),TRc,SRc+ZRc,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[ORc-1]or 0,bb.teamDps or 0))
end
if LRc.lastW and LRc.lastW>0 and LRc.lastWT then
table.insert(LRc.waveSec,NRc-LRc.lastWT)
end
if LRc.paidT and ORc>0 and NRc-LRc.paidT<15 then
table.insert(LRc.skip,NRc-LRc.paidT)
end
LRc.paidT=nil
if ORc>0 then
LRc.alive[tostring(ORc)]=bb.hpAliveRaw or 0
end
LRc.lastW,LRc.lastWT=ORc,NRc
end
local bSc=workspace:FindFirstChild(Gje[4276])
if bSc and ORc>0 then
LRc.timer[tostring(ORc)]=math.max(LRc.timer[tostring(ORc)]or 0,tonumber(bSc.Value)or 0)
end
local cSc=PRc-(bb.lastMoneyR or PRc)
bb.lastMoneyR=PRc
bb.incomeLog=bb.incomeLog or{}
if cSc>0 then
table.insert(bb.incomeLog,{t=NRc,y=cSc})
end
while bb.incomeLog[1]and NRc-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
end
local dSc=0
for eSc,fSc in ipairs(bb.incomeLog)do
dSc=dSc+fSc.y
end
local gSc=math.min(30,NRc-(bb.startT or NRc))
bb.incomeRate=gSc>=8 and dSc/gSc or nil
for hSc,iSc in ipairs(bb.enemies)do
local jSc=iSc.m
local kSc=bb.track[jSc]
if not kSc then
local lSc=jSc._stats
local mSc=jSc:FindFirstChildOfClass(Gje[2407])
local nSc=MRc.cfgById[lSc.id.Value]
local oSc=nSc and gb.baseStats(MRc,nSc)
if mSc and oSc and ORc>0 then
local pSc=oSc*MRc.hpRaw*gb.waveScale(MRc,ORc,MRc.list[ORc])
if pSc>0 and mSc.MaxHealth>0 then
table.insert(LRc.hp,mSc.MaxHealth/pSc)
end
end
bb.track[jSc]={t=NRc,p=iSc.prog,sp=(lSc:FindFirstChild(Gje[4277])and tonumber(lSc.speed.Value))or 1}
if mSc and mSc.MaxHealth>0 then
bb.enemyHpSum=(bb.enemyHpSum or 0)+mSc.MaxHealth
end
if ORc>0 then
LRc.spawn[tostring(ORc)]=(LRc.spawn[tostring(ORc)]or 0)+1
LRc.spawnLast[tostring(ORc)]=NRc-(LRc.lastWT or NRc)
end
elseif not kSc.done and NRc-kSc.t>=15 then
kSc.done=true
local qSc=(iSc.prog-kSc.p)/(NRc-kSc.t)/math.max(0.1,kSc.sp)
if qSc>0.001 and iSc.prog<0.95 then
table.insert(LRc.walk,qSc)
