end
local Jbd=Gbd.base/Ibd
local Kbd,Lbd=0,0
local Mbd,Nbd=Fbd.foes or{},Gbd.foes or{}
for Obd,Pbd in pairs(Nbd)do
if Pbd.prog>=bb.BASE_END then
Kbd=Kbd+Pbd.hp
local Qbd=Mbd[Obd]
if Qbd then
Lbd=Lbd+math.max(0,Qbd.hp-Pbd.hp)
end
end
end
for Rbd,Sbd in pairs(Mbd)do
if Sbd.prog>=bb.BASE_END and not Nbd[Rbd]then
