bb.mergeIds={}
function bb.mergeScan()
bb.mergePlan,bb.mergeIds=nil,{}
if not bb.random then
return
end
local Xhd=N.session()
local Yhd=false
bb.cloneCard=false
for Zhd,_hd in pairs((Xhd and Xhd.ingame_spells)or{})do
if _hd==Gje[4496]then
Yhd=true
elseif _hd==Gje[4560]then
bb.cloneCard=true
end
end
local aid={}
local cid=P.fh.noMerge or{}
for did,eid in ipairs(bb.mine or{})do
local fid=eid._stats
local gid=fid.id.Value
if not V.isFarm(gid)and not V.allyBuff(gid)and not V.idol(gid)and fid:FindFirstChild(Gje[2400])and(cid[gid]or 0)<2 then
local hid,iid=pcall(bb.liveDps,eid,gid)
aid[gid]=aid[gid]or{}
table.insert(aid[gid],{m=eid,lvl=fid.upgrade.Value,max=fid.max_upgrade.Value,dps=hid and iid or 0})
end
end
local jid={}
for kid,lid in ipairs(bb.team or{})do
if lid.hand then
jid[lid.id]=true
end
end
local nid={}
for oid,qid in pairs(aid)do
table.sort(qid,function(rid,sid)
if rid.dps~=sid.dps then
return rid.dps>sid.dps
end
return rid.lvl>sid.lvl
end)
table.insert(nid,{id=oid,dps=qid[1].dps*bb.airBoost(qid[1].m)*bb.reach(qid[1].m)})
end
table.sort(nid,function(tid,vid)
return tid.dps>vid.dps
end)
for wid=1,math.min(3,#nid)do
bb.mergeIds[nid[wid].id]=true
end
local xid
for yid,zid in pairs(aid)do
local Aid=table.clone(zid)
table.sort(Aid,function(Bid,Cid)
if Bid.lvl~=Cid.lvl then
return Bid.lvl<Cid.lvl
end
return Bid.dps<Cid.dps
end)
for Did,Eid in ipairs(Aid)do
if Eid.m==bb.freshM and Did>1 then
table.remove(Aid,Did)
table.insert(Aid,1,Eid)
break
end
end
local Fid,Gid,Hid,Iid
for Jid,Kid in ipairs(Aid)do
local Lid,Mid=U.flat(Kid.m:GetPivot().Position),Kid.m._stats.range.Value
local Nid,Oid,Pid=0,0,nil
for Qid,Rid in ipairs(zid)do
if Rid~=Kid and(U.flat(Rid.m:GetPivot().Position)-Lid).Magnitude<=Mid then
Nid,Oid=Nid+Rid.dps,Oid+1
if not Pid or Rid.dps>Pid.dps then
Pid=Rid
end
end
end
if Oid>0 then
Fid,Gid,Hid,Iid=Kid,Nid,Oid,Pid
break
end
end
Iid=Iid or zid[1]
local Sid=Iid.dps*bb.airBoost(Iid.m)*bb.reach(Iid.m)*(yid==bb.planId and 2 or 1)
if(bb.mergeIds[yid]or yid==bb.planId)and(Fid or jid[yid])and(not xid or Sid>xid.score)then
xid={id=yid,top=Iid,fresh=Fid,near=Gid or 0,n=Hid or 0,coming=jid[yid],score=Sid}
end
end
bb.planId,bb.freshM=xid and xid.id,xid and xid.fresh and xid.fresh.m
bb.mergeHeldAt=(Yhd and xid and xid.fresh)and(bb.mergeHeldAt or bb.wave())or nil
if not xid then
return F.status(Gje[4474],Gje[4561])
end
local Tid,Uid=bb.wave(),(bb.total or 30)-bb.wave()
local Vid=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local Wid=xid.fresh
local Xid=not Vid and Uid>3
xid.waits=Wid and Wid.lvl<=xid.top.lvl and xid.top.lvl<xid.top.max and Xid or false
local Yid=(not Wid or Wid.lvl>=xid.top.lvl)and xid.coming and Xid
local Zid=bb.cloneCard and xid.top.lvl>=xid.top.max and Xid
local ajd=Wid and Wid.lvl>xid.top.lvl and xid.near<0.3*Wid.dps
xid.ready=Yhd and Wid~=nil and not ajd and(not(xid.waits or Yid or Zid)or Tid-(bb.mergeHeldAt or Tid)>=5)
bb.holdNoCardAt=(xid.waits and not Yhd)and(bb.holdNoCardAt or Tid)or nil
xid.hold=xid.waits and(Yhd or Tid-(bb.holdNoCardAt or Tid)<4)
bb.mergePlan=xid
F.status(Gje[4474],Wid and string.format(Gje[4562],V.name(xid.id),xid.n,xid.n==1 and Gje[4563]or Gje[4564],Wid.lvl,xid.ready and Gje[4565]or(Yhd and Gje[4566]or Gje[4567]))or string.format(Gje[4568],V.name(xid.id)))
end
function bb.mergeHold(bjd)
local cjd=bb.mergePlan
return cjd and cjd.hold and cjd.fresh and cjd.fresh.m==bjd or false
end
function bb.mergeBoost(djd)
local ejd=bb.mergePlan
if not(ejd and ejd.top.m==djd and(ejd.fresh or ejd.coming))then
return 1
end
return bb.mergeHeldAt and 2 or 1.3
end
function bb.mergeSpot(fjd)
if not(bb.random and bb.mergeIds[fjd.id])then
return nil
end
local gjd,hjd
for ijd,jjd in ipairs(bb.mine or{})do
if jjd._stats.id.Value==fjd.id then
local kjd,ljd=pcall(bb.liveDps,jjd,fjd.id)
ljd=kjd and ljd or 0
if not hjd or ljd>hjd then
gjd,hjd=jjd,ljd
end
end
end
return gjd and gjd:GetPivot().Position
end
function bb.mergeMeasure(mjd)
local njd=bb.mergeBefore
if not njd then
return
end
task.delay(2,function()
if not(mjd and mjd.Parent)then
return
end
local ojd,pjd=pcall(bb.liveDps,mjd,mjd._stats.id.Value)
if not ojd then
return
end
local qjd=njd.own+1.5*njd.near
local rjd=P.fh.merge or{n=0,ratio=0}
if qjd>0 then
rjd.n,rjd.ratio=rjd.n+1,rjd.ratio+pjd/qjd
end
P.fh.merge=rjd
local sjd=mjd._stats.id.Value
P.fh.noMerge=P.fh.noMerge or{}
local tjd,ujd=pjd-njd.own,1.5*njd.near
if ujd>0 and tjd<0.1*ujd then
P.fh.noMerge[sjd]=(P.fh.noMerge[sjd]or 0)+1
elseif ujd>0 and tjd>=0.5*ujd then
P.fh.noMerge[sjd]=nil
end
F.log(1,Gje[4491],string.format(Gje[4569],V.name(mjd._stats.id.Value),U.fmt(njd.own),U.fmt(pjd),njd.lvl,U.fmt(njd.near),U.fmt(qjd),njd.top))
end)
end
function bb.farmMergeOk()
local vjd=P.fh.farmMerge
if not(vjd and vjd.n>0)then
return true
end
return vjd.ratio/vjd.n>=0.8
end
function bb.farmMergePair()
local wjd={}
for xjd,yjd in ipairs(bb.mine or{})do
local zjd=yjd._stats.id.Value
if V.isFarm(zjd)and yjd._stats:FindFirstChild(Gje[2120])then
wjd[zjd]=wjd[zjd]or{}
table.insert(wjd[zjd],yjd)
end
end
for Ajd,Bjd in pairs(wjd)do
if#Bjd>=2 then
table.sort(Bjd,function(Cjd,Djd)
return Cjd._stats.upgrade.Value<Djd._stats.upgrade.Value
end)
for Ejd,Fjd in ipairs(Bjd)do
local Gjd,Hjd=U.flat(Fjd:GetPivot().Position),Fjd._stats.range.Value
local Ijd,Jjd=0,0
for Kjd,Ljd in ipairs(Bjd)do
if Ljd~=Fjd and(U.flat(Ljd:GetPivot().Position)-Gjd).Magnitude<=Hjd then
Ijd,Jjd=Ijd+(tonumber(Ljd._stats.farm_amount.Value)or 0),Jjd+1
end
end
if Jjd>0 then
return Fjd,Ijd,Jjd
end
end
end
end
end
function bb.farmMergeSpot(Mjd)
if not(bb.random and bb.farmMergeOk())then
return nil
end
for Njd,Ojd in ipairs(bb.mine or{})do
if Ojd._stats.id.Value==Mjd.id then
