function bb.idolMeasure()
local Xjd
for Yjd,Zjd in ipairs(bb.mine)do
local _jd=Zjd._stats.id.Value
local akd=Zjd._stats:FindFirstChild(Gje[2449])
if not V.isFarm(_jd)and not V.idol(_jd)and akd and akd.Value>0 then
Xjd=Zjd
break
end
end
if not Xjd then
