local fkd=bkd:FindFirstChild(Gje[4353])and tonumber(bkd.buff_damage_multiplier.Value)or 0
return bkd.damage.Value*(1+fkd),dkd and tonumber(ekd)or nil
end
local gkd,hkd=ckd()
