end
local lkd=P.fh.idol or{n=0,dmg=0,cost=0}
lkd.n,lkd.dmg,lkd.cost=lkd.n+1,lkd.dmg+(jkd/gkd-1),lkd.cost+(1-kkd/hkd)
P.fh.idol=lkd
F.log(1,Gje[4346],string.format(Gje[4572],V.name(bkd.id.Value),(jkd/gkd-1)*100,(1-kkd/hkd)*100))
end)
end
function bb.spells()
local mkd=N.session()
local nkd=mkd and mkd.ingame_spells
if type(nkd)~=Gje[2012]or bb.spellBusy then
return
end
local okd=bb.money()
local pkd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local qkd,rkd,skd
for tkd,ukd in ipairs(bb.mine)do
local vkd=ukd._stats.id.Value
if not V.isFarm(vkd)and not V.allyBuff(vkd)and vkd~=Gje[4088]then
local wkd,xkd=pcall(bb.liveDps,ukd,vkd)
local ykd=wkd and xkd and xkd*bb.airBoost(ukd)*bb.reach(ukd)
if ykd and(not skd or ykd>skd)then
qkd,rkd,skd=ukd,xkd,ykd
end
end
end
local zkd=bb.mergePlan
local Akd={}
for Bkd,Ckd in pairs(nkd)do
table.insert(Akd,{slot=Bkd,spell=Ckd,rank=bb.SPELL_ORDER[Ckd]or 9})
end
table.sort(Akd,function(Dkd,Ekd)
return Dkd.rank<Ekd.rank
end)
bb.spellWant=nil
bb.cloneNote=nil
for Fkd,Gkd in ipairs(Akd)do
