local Jkd,Kkd
local Lkd
for Mkd,Nkd in ipairs(bb.mine)do
if Nkd._stats.id.Value==Gje[4088]then
Lkd=Nkd
end
end
local Okd=Lkd and(bb.buffCount[Lkd]or 0)<2
if Ikd==Gje[4573]and okd>=1000 and(Okd or qkd)then
if Okd then
Jkd,Kkd=Lkd,Gje[4574]
else
Jkd,Kkd=qkd,Gje[4575]
end
elseif Ikd==Gje[4496]and zkd and zkd.ready then
if okd>=1000 then
Jkd,Kkd=zkd.fresh.m,string.format(Gje[4576],zkd.n,zkd.n==1 and Gje[4563]or Gje[4564])
bb.mergeBefore={own=zkd.fresh.dps,near=zkd.near,lvl=zkd.fresh.lvl,top=zkd.top.lvl}
else
bb.spellWant=bb.spellWant or{cost=1000,why=Gje[4577]..V.name(zkd.id)}
end
elseif Ikd==Gje[4496]and okd>=1000 and not pkd and not(zkd and zkd.fresh)and bb.farmMergeOk()and bb.farmMergePair()then
local Pkd,Qkd,Rkd=bb.farmMergePair()
Jkd=Pkd
Kkd=string.format(Gje[4578],Rkd,V.name(Pkd._stats.id.Value))
bb.farmMergeBefore={own=tonumber(Pkd._stats.farm_amount.Value)or 0,inc=Qkd}
elseif Ikd==Gje[4560]then
local Skd=not pkd and zkd and zkd.fresh and zkd.top.lvl<zkd.top.max
bb.cloneWaitAt=Skd and(bb.cloneWaitAt or bb.wave())or nil
local Tkd=Skd and bb.wave()-bb.cloneWaitAt<5
local Ukd,Vkd
if not pkd and zkd and zkd.fresh and zkd.top.lvl>=zkd.top.max then
Ukd,Vkd=zkd.top.m,Gje[4579]
elseif not Tkd and qkd then
Ukd,Vkd=qkd,pkd and Gje[4580]or Gje[4581]
end
if Tkd then
bb.cloneNote=string.format(Gje[4582],V.name(zkd.id),zkd.top.lvl,zkd.top.max,5-(bb.wave()-bb.cloneWaitAt))
end
if Ukd and okd>=5000 then
Jkd,Kkd=Ukd,Vkd
elseif Ukd then
local Wkd,Xkd=pcall(bb.liveDps,Ukd,Ukd._stats.id.Value)
Xkd=Wkd and tonumber(Xkd)or 0
if Xkd>=(bb.bestRate or 0)*5000*0.5 then
bb.spellWant=bb.spellWant or{cost=5000,why=Gje[4583]..V.name(Ukd._stats.id.Value),rate=Xkd/5000}
bb.cloneNote=Gje[4584]..V.name(Ukd._stats.id.Value)
else
bb.cloneNote=string.format(Gje[4585],V.name(Ukd._stats.id.Value),U.fmt(Xkd),U.fmt((bb.bestRate or 0)*5000))
end
end
elseif Ikd==Gje[4493]and not pkd and bb.wave()>=8 and not bb.hasGeneral()then
local Ykd,Zkd=bb.ritualTarget()
if Ykd and okd>=10000 then
Jkd,Kkd=Ykd,Zkd
elseif Ykd then
bb.spellWant=bb.spellWant or{cost=10000,why=Gje[4586]..Zkd..Gje[2673]}
end
elseif Ikd==Gje[2098]and okd>=10000 and not pkd and bb.summonWorth()then
Jkd,Kkd=false,Gje[4587]
elseif Ikd==Gje[4497]and okd>=2500 and not pkd and bb.summonWorth()then
Jkd,Kkd=false,Gje[4588]
end
if Kkd then
bb.spellBusy=true
local _kd={}
for ald,bld in ipairs(workspace._UNITS:GetChildren())do
_kd[bld]=true
end
local cld
if Jkd then
local dld=Jkd._stats
local eld,fld=pcall(bb.liveDps,Jkd,dld.id.Value)
cld={id=dld.id.Value,pos=Jkd:GetPivot().Position,dps=eld and tonumber(fld)or 0,lvl=dld.upgrade.Value,spent=dld:FindFirstChild(Gje[4110])and tonumber(dld.total_spent.Value)or 0}
end
task.spawn(function()
local gld
if Jkd then
gld=F.request(Gje[4505],Gje[4506],Hkd,Jkd)
else
gld=F.request(Gje[4505],Gje[4506],Hkd)
end
task.wait(1.5)
local hld=Jkd and V.name(Jkd._stats.id.Value)or Gje[933]
if gld and(N.session().ingame_spells or{})[Hkd]~=Ikd then
F.log(1,Gje[4491],string.format(Gje[4589],bb.SPELL_NAMES[Ikd]or tostring(Ikd),Jkd and(Gje[2595]..hld)or Gje[933],Kkd))
F.status(Gje[4384],string.format(Gje[4590],bb.SPELL_NAMES[Ikd]or tostring(Ikd),Jkd and(Gje[2595]..hld)or Gje[933],Kkd))
if Ikd==Gje[4496]then
if cld and V.isFarm(cld.id)then
pcall(bb.farmMergeMeasure,Jkd)
else
pcall(bb.mergeMeasure,Jkd)
end
