if Ikd==Gje[4573]and Jkd then
bb.buffCount[Jkd]=(bb.buffCount[Jkd]or 0)+1
end
if(Ikd==Gje[4560]or Ikd==Gje[4493])and cld then
pcall(bb.newUnitMeasure,Ikd,Jkd,hld,cld,_kd)
end
else
F.backoff(Gje[4505],15)
F.log(2,Gje[4491],tostring(Ikd)..Gje[4591]..(Jkd and(Gje[2595]..hld)or Gje[933]))
end
bb.spellBusy=false
end)
return
end
end
end
function bb.trainCount()
local ild=P.train.on
if not(ild and bb.trainee)then
return
end
local jld=0
for kld,lld in ipairs(bb.mine)do
local mld=lld._stats
local nld=mld:FindFirstChild(Gje[2388])and mld.uuid.Value
local pld=nld==bb.trainee and mld:FindFirstChild(ild.what==Gje[2663]and Gje[4592]or Gje[2403])
if pld then
jld=jld+(tonumber(pld.Value)or 0)
end
end
bb.trainTk=math.max(bb.trainTk or 0,jld)
F.status(Gje[3232],string.format(Gje[4593],V.name(ild.id),bb.trainTk,ild.what,U.fmt(ild.have+(ild.got or 0)+bb.trainTk),U.fmt(ild.need)))
end
function bb.trainDone(qld,rld)
local sld=P.train.on
if not(sld and bb.trainee)then
return
end
bb.trainCount()
local tld=bb.trainTk or 0
sld.got=(sld.got or 0)+tld
local uld=P.trainSim[qld]and tonumber(P.trainSim[qld].tk)
if not bb.joinedMid then
local vld=P.train.real[qld]or{n=0,sum=0}
vld.n,vld.sum=vld.n+1,vld.sum+tld
P.train.real[qld]=vld
if uld and uld>0 then
local wld=P.train.cal
wld.real,wld.sim,wld.n=(wld.real or 0)+tld,(wld.sim or 0)+uld,(wld.n or 0)+1
end
end
table.insert(P.train.log,1,{key=qld,got=tld,won=rld,at=os.time()})
while#P.train.log>20 do
table.remove(P.train.log)
end
F.log(1,Gje[3225],string.format(Gje[4594],V.name(sld.id),tld,sld.what,rld and Gje[2756]or Gje[2757],uld and string.format(Gje[4595],uld)or Gje[933],U.fmt(ib.realHave(sld)),U.fmt(sld.need)))
if not rld then
P.train.bad[qld]=os.time()+3600
F.log(1,Gje[3225],Gje[4596])
end
end
function bb.realKills()
local xld=M:FindFirstChild(Gje[2075])
local yld=xld and xld:FindFirstChild(Gje[2663])
return yld and tonumber(yld.Value)or nil
end
function bb.finish()
if bb.finished then
return
end
bb.finished=true
bb.killsEnd=bb.realKills()
local zld,Ald=pcall(bb.holdFold)
if not zld then
F.log(1,Gje[2398],Gje[4597]..tostring(Ald))
end
local Bld=bb.galeStat
if type(Bld)==Gje[2012]and(Bld.on+Bld.near)>=1 then
F.log(1,Gje[4364],string.format(Gje[4598],math.floor(Bld.on+0.5),math.floor(Bld.near+0.5),math.floor(Bld.wait+0.5)))
end
bb.galeStat=nil
local Cld
local Dld=U.now()
while U.now()-Dld<8 do
Cld=bb.result or(N.GUIS.results_ui and N.GUIS.results_ui.settings)
if Cld then
break
end
task.wait(0.25)
end
local Eld=Cld and Cld.victory or false
local Fld=bb.infinite and bb.wave()or nil
if Fld then
Eld=true
end
if bb.fb and not Fld then
pcall(bb.fbTick)
pcall(bb.fbNote,Eld)
local Gld=bb.fb
if Gld.assassin then
F.log(1,Gje[2680],string.format(Gje[4599],Gld.name or Gld.id,Eld and Gje[2756]or Gje[2757],math.floor((Gld.share or 1)*100+0.5),math.floor((Gld.low or 1)*100+0.5),math.floor(U.now()-Gld.t0),math.floor((Gld.gp or 0)*100+0.5)))
end
end
local Hld=bb.key
local Ild=W.rec(Hld)
if Fld and not bb.joinedMid and not bb.stopping then
Ild.waveSum,Ild.waveN=(tonumber(Ild.waveSum)or 0)+Fld,(tonumber(Ild.waveN)or 0)+1
Ild.waveBest=math.max(tonumber(Ild.waveBest)or 0,Fld)
end
if Fld and(tonumber(P.infResults)or 0)<3 and type(Cld)==Gje[2012]then
P.infResults=(tonumber(P.infResults)or 0)+1
local Jld={}
for Kld,Lld in pairs(Cld)do
table.insert(Jld,type(Lld)==Gje[2012]and(Kld..Gje[2677])or(Kld..Gje[2678]..tostring(Lld)))
end
table.sort(Jld)
